   pane decides, not the window, so a wider chat column flips it too. */
.fl-wrap{container-type:inline-size}
.fl{display:grid;color:var(--dim);font-size:11.5px;
  grid-template-columns:24px 24px minmax(0,1fr) auto;
  grid-template-areas:
    "reop skip open    in-open"
