export function render(rows: string[][], header: string) {
  const W = rows[0].length
  const widths = Array.from({ length: W }, (_, c) => Math.max(...rows.map((r) => r[c].length)))
  const lines = rows.map((r) => '  "' + r.map((t, c) => t.padEnd(widths[c])).join(' ').trimEnd() + '"')
  return header + '\n' + contentText + '\ngrid\n' + lines.join('\n') + '\n'
}

export function evaluate(text: string) {
  const d = parseGrid(text)
  const { errors, index } = check(d)
  if (errors.length) return { errors, warnings: [] as string[], w: 0, h: 0 }
  const r = resolveGrid(d, index)
  return { errors, warnings: r.warnings, w: r.width, h: r.height }
}
